import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import '../styles/Chatbot.css';
import { useAuthContext } from '../hooks/useAuthContext';
import { useNavigate } from 'react-router-dom';

const Chatbot = () => {
  const [userInput, setUserInput] = useState('');
  const [chatMessages, setChatMessages] = useState([]);
  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);

  const { user } = useAuthContext();
  const navigate = useNavigate();

  const viewConversations = useCallback(async () => {
    if (!user?.token) return;

    try {
      const res = await axios.get('http://localhost:4000/api/chat', {
        headers: { Authorization: `Bearer ${user.token}` }
      });
      setConversations(res.data);
    } catch (err) {
      console.error('Failed to fetch history:', err);
    }
  }, [user?.token]);

  useEffect(() => {
    if (!user) {
      navigate('/auth');
    } else {
      viewConversations();
    }
  }, [user, navigate, viewConversations]);

  if (!user) return null;

  const sendMessage = async () => {
    if (userInput.trim() === '') return;

    try {
      const response = await axios.post(
        'http://localhost:4000/api/chat',
        { message: userInput },
        {
          headers: { Authorization: `Bearer ${user.token}` }
        }
      );

      // Append to live messages so they render immediately
      setChatMessages(prev => [
        ...prev,
        { text: userInput, isUser: true },
        { text: response.data.botResponse, isUser: false }
      ]);

      // Optionally refresh sidebar topics after sending
      // await viewConversations();
    } catch (error) {
      console.error('Error sending message', error);
    }

    setUserInput('');
  };

  const groupConversationsByDate = (convos) => {
    const groups = {};

    convos.forEach((chat) => {
      const date = new Date(chat.createdAt);
      const today = new Date();
      const label =
        date.toDateString() === today.toDateString()
          ? 'Today'
          : date.toLocaleDateString('en-US', { weekday: 'long' });

      if (!groups[label]) groups[label] = [];
      groups[label].push(chat);
    });

    return groups;
  };

  // Merge selected conversation history with live messages
  const displayedMessages = [
    ...(selectedConversation?.messages || []),
    ...chatMessages
  ];

  return (
    <div className="chatbot">
      {/* Sidebar */}
      <div className="chat-history">
        <h3>Past Conversations</h3>
        {Object.entries(groupConversationsByDate(conversations)).map(([label, chats]) => (
          <div key={label}>
            <h4>{label}</h4>
            <ul>
              {chats.map((chat) => (
                <li
                  key={chat._id}
                  onClick={() => {
                    setSelectedConversation(chat);
                    setChatMessages([]); // clear live buffer when switching
                  }}
                  className={selectedConversation?._id === chat._id ? 'selected' : ''}
                >
                  <strong>{chat.topic || 'Untitled'}</strong>
                  <div className="timestamp">
                    {new Date(chat.createdAt).toLocaleTimeString()}
                  </div>
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>

      {/* Chat Window */}
      <div className="chat-window">
        <div className="messages">
          {displayedMessages.map((msg, index) => (
            <div key={index} className={msg.isUser ? 'user' : 'bot'}>
              {msg.text}
            </div>
          ))}
        </div>

        <div className="input-area">
          <input
            type="text"
            value={userInput}
            onChange={(e) => setUserInput(e.target.value)}
            placeholder="Type your message..."
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </div>
    </div>
  );
};

export default Chatbot;
